import json
import sys
import time
import urllib.error
import urllib.request
from collections import Counter
from datetime import datetime, timezone

BASE = "http://localhost:8080"
RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May 2025 inclusive
MAX_ATTEMPTS = 60
REGIONS = ["north", "south", "east", "west"]

log_counts = Counter()
token = None


def log(msg):
    print(msg, file=sys.stderr, flush=True)


def get_token():
    global token
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        token = json.loads(r.read())["token"]
    return token


def wait_seconds(err_headers, body):
    ra = err_headers.get("Retry-After") if err_headers else None
    if ra:
        try:
            return float(ra)
        except ValueError:
            pass
    try:
        data = json.loads(body)
        for key in ("retry_after", "retry_after_seconds", "wait_seconds"):
            if key in data:
                return float(data[key])
    except (ValueError, TypeError, AttributeError):
        pass
    return None


def fetch(path, auth=True):
    """GET a path, retrying through token expiry, rate limits and transient failures.
    Returns parsed JSON, or None for 404."""
    global token
    for attempt in range(1, MAX_ATTEMPTS + 1):
        if auth and token is None:
            get_token()
        headers = {"Authorization": "Bearer " + token} if auth else {}
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                status, body, hdrs = r.status, r.read(), r.headers
        except urllib.error.HTTPError as e:
            status, body, hdrs = e.code, e.read(), e.headers
        except OSError as e:
            log(f"network error on {path}: {e}; attempt {attempt}")
            time.sleep(min(2 ** attempt, 30))
            continue

        if status == 200:
            return json.loads(body)
        if status == 404:
            return None
        log_counts[status] += 1
        if log_counts[status] <= 3:
            log(f"HTTP {status} on {path} (attempt {attempt}): {body[:300]!r} headers={dict(hdrs)}")
        if status in (401, 403):
            token = None
            time.sleep(1)
        elif status == 429:
            secs = wait_seconds(hdrs, body)
            time.sleep(secs if secs is not None else min(2 ** attempt, 60))
        elif status >= 500:
            time.sleep(min(2 ** attempt, 30))
        else:
            log(f"unexpected HTTP {status} on {path}: {body[:300]!r}")
            time.sleep(min(2 ** attempt, 30))
    raise RuntimeError(f"gave up on {path} after {MAX_ATTEMPTS} attempts")


def parse_ts(s):
    t = datetime.fromisoformat(s.replace("Z", "+00:00"))
    if t.tzinfo is None:
        raise ValueError(f"naive timestamp, no offset: {s}")
    return t.astimezone(timezone.utc)


def round_half_up_discount(amount_cents, pct):
    # amount * (100 - pct) / 100, rounded half up to a whole cent. All values non-negative.
    return (amount_cents * (100 - pct) + 50) // 100


def main():
    # 1. Collect every listed order, following "next" links from page 1.
    listing = []  # all items as received, in order
    seen = {}      # id -> first copy
    dup_copies = []
    path = "/orders?page=1"
    pages = 0
    total_pages = None
    while path:
        page = fetch(path)
        pages += 1
        total_pages = page["total_pages"]
        for item in page["items"]:
            listing.append(item)
            oid = item["id"]
            if oid in seen:
                dup_copies.append((oid, seen[oid] == item))
            else:
                seen[oid] = item
        path = page["next"]
        log(f"page {page['page']} of {total_pages}: {len(page['items'])} items, next={path}")

    log(f"pages fetched: {pages} (total_pages reported {total_pages})")
    if pages != total_pages:
        raise RuntimeError(f"fetched {pages} pages but service reports {total_pages}")

    identical_dups = sum(1 for _, same in dup_copies if same)
    conflicting_dups = [oid for oid, same in dup_copies if not same]
    log(f"listed items: {len(listing)}, distinct ids: {len(seen)}, repeated copies: {len(dup_copies)} "
        f"(identical: {identical_dups}, conflicting: {len(conflicting_dups)})")
    if conflicting_dups:
        raise RuntimeError(f"repeated order ids with differing content: {conflicting_dups[:10]}")

    status_counts = Counter(o["status"] for o in seen.values())
    log(f"status counts over distinct orders: {dict(status_counts)}")

    # 2. Filter: exact status "shipped", UTC date range.
    qualifying = []
    for o in seen.values():
        if not isinstance(o["amount_cents"], int):
            raise RuntimeError(f"non-integer amount on {o['id']}: {o['amount_cents']!r}")
        if o["status"] != "shipped":
            continue
        t = parse_ts(o["placed_at"])
        if RANGE_START <= t < RANGE_END:
            qualifying.append(o)
    log(f"qualifying orders: {len(qualifying)}")

    # 3. Look up each distinct customer once.
    customers = {}
    for cid in sorted({o["customer_id"] for o in qualifying}):
        c = fetch(f"/customers/{cid}")
        if c is None:
            raise RuntimeError(f"customer {cid} not found (404)")
        customers[cid] = c
    log(f"customers looked up: {len(customers)}")

    # 4. Discount per order, round per order, sum by region.
    total = 0
    by_region = {r: 0 for r in REGIONS}
    unknown_regions = Counter()
    for o in qualifying:
        c = customers[o["customer_id"]]
        discounted = round_half_up_discount(o["amount_cents"], c["discount_pct"])
        total += discounted
        if c["region"] in by_region:
            by_region[c["region"]] += discounted
        else:
            unknown_regions[c["region"]] += discounted
    if unknown_regions:
        raise RuntimeError(f"orders with unexpected region values: {dict(unknown_regions)}")

    assert sum(by_region.values()) == total

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": len(dup_copies),
        "by_region": by_region,
    }
    log(f"HTTP non-200 counts: {dict(log_counts)}")
    print(json.dumps(result, indent=2))
    return result


if __name__ == "__main__":
    main()
